 24→export class DeviceApprovalController {
 25→  constructor(private readonly deviceApprovalService: DeviceApprovalService) {}
 26→
 27→  @Post('request')
 28→  @Throttle({ default: { limit: 3, ttl: 60000 } })
 29→  @ApiOperation({
 30→    summary: 'Create device approval request',
 31→    description:
 32→      'New device creates an approval request with an ephemeral ' +
 33→      'public key for ECIES key exchange. Request expires after ' +
 34→      '5 minutes.',
 35→  })
 36→  @ApiResponse({
 37→    status: 201,
 38→    description: 'Approval request created',
 39→    schema: {
 40→      properties: {
 41→        requestId: { type: 'string', format: 'uuid' },
 42→      },
 43→    },
 44→  })
 45→  @ApiResponse({ status: 401, description: 'Unauthorized' })
 46→  async createRequest(
 47→    @Request() req: RequestWithUser,
 48→    @Body() dto: CreateApprovalDto
 49→  ): Promise<{ requestId: string }> {
 50→    return this.deviceApprovalService.createRequest(req.user.id, dto);
 51→  }
 52→
 53→  @Get(':requestId/status')
 54→  @ApiOperation({
 55→    summary: 'Poll approval request status',
 56→    description:
 57→      'New device polls this endpoint to check if the request ' +
 58→      'has been approved, denied, or expired. Returns the ' +
 59→      'encrypted factor key on approval.',
 60→  })
 61→  @ApiResponse({
 62→    status: 200,
 63→    description: 'Approval status',
 64→    schema: {
 65→      properties: {
 66→        status: {
 67→          type: 'string',
 68→          enum: ['pending', 'approved', 'denied', 'expired'],
 69→        },
 70→        encryptedFactorKey: {
 71→          type: 'string',
 72→          nullable: true,
 73→          description: 'ECIES-encrypted factor key (hex)',
 74→        },
 75→      },
 76→    },
 77→  })
 78→  @ApiResponse({ status: 401, description: 'Unauthorized' })
 79→  @ApiResponse({
 80→    status: 404,
 81→    description: 'Request not found',
 82→  })
 83→  async getStatus(
 84→    @Request() req: RequestWithUser,
 85→    @Param('requestId', ParseUUIDPipe) requestId: string
 86→  ): Promise<{ status: string; encryptedFactorKey?: string }> {
 87→    return this.deviceApprovalService.getStatus(requestId, req.user.id);
 88→  }
 89→
 90→  @Get('pending')
 91→  @ApiOperation({
 92→    summary: 'List pending approval requests',
 93→    description:
 94→      'Existing device fetches all non-expired pending approval ' +
 95→      'requests for the authenticated user.',
 96→  })
 97→  @ApiResponse({
 98→    status: 200,
 99→    description: 'List of pending approval requests',
100→    schema: {
101→      type: 'array',
102→      items: {
103→        properties: {
104→          requestId: { type: 'string', format: 'uuid' },
105→          deviceId: { type: 'string' },
106→          deviceName: { type: 'string' },
107→          ephemeralPublicKey: { type: 'string' },
108→          createdAt: { type: 'string', format: 'date-time' },
109→          expiresAt: { type: 'string', format: 'date-time' },
110→        },
111→      },
112→    },
113→  })
114→  @ApiResponse({ status: 401, description: 'Unauthorized' })
115→  async getPending(@Request() req: RequestWithUser): Promise<
116→    Array<{
117→      requestId: string;
118→      deviceId: string;
119→      deviceName: string;
120→      ephemeralPublicKey: string;
121→      createdAt: Date;
122→      expiresAt: Date;
123→    }>
124→  > {
125→    return this.deviceApprovalService.getPending(req.user.id);
126→  }
127→
128→  @Post(':requestId/respond')
129→  @ApiOperation({
130→    summary: 'Respond to approval request',
131→    description:
132→      'Existing device approves or denies an approval request. ' +
133→      'On approve, includes the ECIES-encrypted factor key.',
134→  })
135→  @ApiResponse({
136→    status: 200,
137→    description: 'Response recorded',
138→  })
139→  @ApiResponse({ status: 400, description: 'Already responded or expired' })
140→  @ApiResponse({ status: 401, description: 'Unauthorized' })
141→  @ApiResponse({ status: 404, description: 'Request not found' })
142→  async respond(
143→    @Request() req: RequestWithUser,
144→    @Param('requestId', ParseUUIDPipe) requestId: string,
145→    @Body() dto: RespondApprovalDto
146→  ): Promise<void> {
147→    return this.deviceApprovalService.respond(requestId, req.user.id, dto);
148→  }
149→
150→  @Delete(':requestId')
151→  @ApiOperation({
152→    summary: 'Cancel approval request',
153→    description:
154→      'New device cancels its own pending approval request ' +
155→      '(cleanup on navigation away or recovery phrase used).',
156→  })
157→  @ApiResponse({ status: 200, description: 'Request cancelled' })
158→  @ApiResponse({ status: 401, description: 'Unauthorized' })
159→  @ApiResponse({
160→    status: 404,
161→    description: 'Request not found or not pending',
162→  })
163→  async cancel(
164→    @Request() req: RequestWithUser,
165→    @Param('requestId', ParseUUIDPipe) requestId: string
166→  ): Promise<void> {
167→    return this.deviceApprovalService.cancel(requestId, req.user.id);
168→  }
169→}
