  1→import { Injectable, NotFoundException, BadRequestException } from '@nestjs/common';
  2→import { InjectRepository } from '@nestjs/typeorm';
  3→import { Repository, MoreThan } from 'typeorm';
  4→import { DeviceApproval } from './device-approval.entity';
  5→import { CreateApprovalDto } from './dto/create-approval.dto';
  6→import { RespondApprovalDto } from './dto/respond-approval.dto';
  7→
  8→/** Approval request TTL: 5 minutes */
  9→const TTL_MS = 5 * 60 * 1000;
 10→
 11→/** Maximum concurrent pending approval requests per user */
 12→const MAX_PENDING_REQUESTS = 5;
 13→
 14→@Injectable()
 15→export class DeviceApprovalService {
 16→  constructor(
 17→    @InjectRepository(DeviceApproval)
 18→    private readonly repo: Repository<DeviceApproval>
 19→  ) {}
 20→
 21→  /**
 22→   * Create a new approval request for a device.
 23→   * Sets expiresAt to 5 minutes from now.
 24→   */
 25→  async createRequest(userId: string, dto: CreateApprovalDto): Promise<{ requestId: string }> {
 26→    const pendingCount = await this.repo.count({
 27→      where: {
 28→        userId,
 29→        status: 'pending' as const,
 30→        expiresAt: MoreThan(new Date()),
 31→      },
 32→    });
 33→
 34→    if (pendingCount >= MAX_PENDING_REQUESTS) {
 35→      throw new BadRequestException(
 36→        `Maximum of ${MAX_PENDING_REQUESTS} pending approval requests allowed`
 37→      );
 38→    }
 39→
 40→    const approval = this.repo.create({
 41→      userId,
 42→      deviceId: dto.deviceId,
 43→      deviceName: dto.deviceName,
 44→      ephemeralPublicKey: dto.ephemeralPublicKey,
 45→      status: 'pending',
 46→      expiresAt: new Date(Date.now() + TTL_MS),
 47→    });
 48→
 49→    const saved = await this.repo.save(approval);
 50→    return { requestId: saved.id };
 51→  }
 52→
 53→  /**
 54→   * Get the status of an approval request.
 55→   * Auto-expires pending requests that have passed their TTL.
 56→   */
 57→  async getStatus(
 58→    requestId: string,
 59→    userId: string
 60→  ): Promise<{
 61→    status: string;
 62→    encryptedFactorKey?: string;
 63→  }> {
 64→    const approval = await this.repo.findOne({
 65→      where: { id: requestId, userId },
 66→    });
 67→
 68→    if (!approval) {
 69→      throw new NotFoundException('Approval request not found');
 70→    }
 71→
 72→    // Auto-expire pending requests past TTL
 73→    if (approval.status === 'pending' && approval.expiresAt < new Date()) {
 74→      approval.status = 'expired';
 75→      await this.repo.save(approval);
 76→    }
 77→
 78→    return {
 79→      status: approval.status,
 80→      ...(approval.encryptedFactorKey ? { encryptedFactorKey: approval.encryptedFactorKey } : {}),
 81→    };
 82→  }
 83→
 84→  /**
 85→   * Get all pending (non-expired) approval requests for a user.
 86→   */
 87→  async getPending(userId: string): Promise<
 88→    Array<{
 89→      requestId: string;
 90→      deviceId: string;
 91→      deviceName: string;
 92→      ephemeralPublicKey: string;
 93→      createdAt: Date;
 94→      expiresAt: Date;
 95→    }>
 96→  > {
 97→    const approvals = await this.repo.find({
 98→      where: {
 99→        userId,
100→        status: 'pending' as const,
101→        expiresAt: MoreThan(new Date()),
102→      },
103→      order: { createdAt: 'DESC' },
104→    });
105→
106→    return approvals.map((a) => ({
107→      requestId: a.id,
108→      deviceId: a.deviceId,
109→      deviceName: a.deviceName,
110→      ephemeralPublicKey: a.ephemeralPublicKey,
111→      createdAt: a.createdAt,
112→      expiresAt: a.expiresAt,
113→    }));
114→  }
115→
116→  /**
117→   * Respond to an approval request (approve or deny).
118→   * On approve, stores the ECIES-encrypted factor key.
119→   */
120→  async respond(requestId: string, userId: string, dto: RespondApprovalDto): Promise<void> {
121→    await this.repo.manager.transaction(async (manager) => {
122→      const approval = await manager.findOne(DeviceApproval, {
123→        where: { id: requestId, userId },
124→        lock: { mode: 'pessimistic_write' },
125→      });
126→
127→      if (!approval) {
128→        throw new NotFoundException('Approval request not found');
129→      }
130→
131→      if (approval.status !== 'pending') {
132→        throw new BadRequestException('Approval request has already been responded to');
133→      }
134→
135→      if (approval.expiresAt < new Date()) {
136→        approval.status = 'expired';
137→        await manager.save(approval);
138→        throw new BadRequestException('Approval request has expired');
139→      }
140→
141→      // H-02: Prevent self-approval — responding device must differ from requesting device
142→      if (dto.respondedByDeviceId === approval.deviceId) {
143→        throw new BadRequestException('A device cannot approve its own request');
144→      }
145→
146→      if (dto.action === 'approve') {
147→        // H-03: Require encryptedFactorKey when approving (defense-in-depth)
148→        if (!dto.encryptedFactorKey) {
149→          throw new BadRequestException('encryptedFactorKey is required when approving');
150→        }
151→        approval.encryptedFactorKey = dto.encryptedFactorKey;
152→      }
153→
154→      approval.status = dto.action === 'approve' ? 'approved' : 'denied';
155→      approval.respondedBy = dto.respondedByDeviceId;
156→      await manager.save(approval);
157→    });
158→  }
159→
160→  /**
161→   * Cancel a pending approval request.
162→   * Only works for pending requests owned by the calling user.
163→   */
164→  async cancel(requestId: string, userId: string): Promise<void> {
165→    const approval = await this.repo.findOne({
166→      where: { id: requestId, userId },
167→    });
168→
169→    if (!approval) {
170→      throw new NotFoundException('Approval request not found');
171→    }
172→
173→    if (approval.status !== 'pending') {
174→      throw new NotFoundException('Only pending requests can be cancelled');
175→    }
176→
177→    await this.repo.remove(approval);
178→  }
179→}
180→

  1→import { useCallback } from 'react';
  2→import {
  3→  COREKIT_STATUS,
  4→  generateFactorKey,
  5→  keyToMnemonic,
  6→  mnemonicToKey,
  7→  TssShareType,
  8→  FactorKeyTypeShareDescription,
  9→  factorKeyCurve,
 10→} from '@web3auth/mpc-core-kit';
 11→import { Point } from '@tkey/common-types';
 12→import BN from 'bn.js';
 13→import { useCoreKit } from '../lib/web3auth/core-kit-provider';
 14→import { useMfaStore } from '../stores/mfa.store';
 15→
 16→export type FactorInfo = {
 17→  factorPubHex: string;
 18→  description: string;
 19→  type: string;
 20→  /** Additional metadata set during createFactor (e.g. deviceId, browserName) */
 21→  additionalMetadata?: Record<string, string>;
 22→};
 23→
 24→export function useMfa() {
 25→  const { coreKit, syncStatus } = useCoreKit();
 26→
 27→  const isMfaEnabled = useMfaStore((s) => s.isMfaEnabled);
 28→  const isEnrolling = useMfaStore((s) => s.isEnrolling);
 29→  const factorCount = useMfaStore((s) => s.factorCount);
 30→  const threshold = useMfaStore((s) => s.threshold);
 31→
 32→  /**
 33→   * Check MFA status from Core Kit key details.
 34→   * MFA is enabled when totalFactors > 2 (every account starts with 2
 35→   * default factors: JWT verifier share + hashedShare cloud custodial key).
 36→   */
 37→  const checkMfaStatus = useCallback((): {
 38→    isMfaEnabled: boolean;
 39→    totalFactors: number;
 40→    threshold: number;
 41→  } => {
 42→    if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) {
 43→      return { isMfaEnabled: false, totalFactors: 0, threshold: 0 };
 44→    }
 45→    try {
 46→      const details = coreKit.getKeyDetails();
 47→      const enabled = details.totalFactors > 2;
 48→      useMfaStore.getState().setMfaEnabled(enabled);
 49→      useMfaStore.getState().setFactorDetails(details.totalFactors, details.threshold);
 50→      return {
 51→        isMfaEnabled: enabled,
 52→        totalFactors: details.totalFactors,
 53→        threshold: details.threshold,
 54→      };
 55→    } catch {
 56→      return { isMfaEnabled: false, totalFactors: 0, threshold: 0 };
 57→    }
 58→  }, [coreKit]);
 59→
 60→  /**
 61→   * Enable MFA. Returns 24-word recovery mnemonic.
 62→   * CRITICAL: commitChanges() must be called before enableMFA() in manualSync mode.
 63→   */
 64→  const enableMfa = useCallback(async (): Promise<string> => {
 65→    if (!coreKit) throw new Error('Core Kit not initialized');
 66→    if (coreKit.status !== COREKIT_STATUS.LOGGED_IN) {
 67→      throw new Error('Must be logged in to enable MFA');
 68→    }
 69→
 70→    const store = useMfaStore.getState();
 71→    if (store.isMfaEnabled) {
 72→      throw new Error('MFA is already enabled');
 73→    }
 74→
 75→    useMfaStore.getState().setEnrolling(true);
 76→    try {
 77→      // Commit any pending changes first (CRITICAL for manualSync mode -- Pitfall 1)
 78→      await coreKit.commitChanges();
 79→
 80→      // Capture TSS public key BEFORE enableMFA for stability verification (MFA-04)
 81→      const preMfaTssPub = coreKit.getKeyDetails().tssPubKey;
 82→
 83→      // enableMFA creates device factor + recovery factor atomically
 84→      const backupFactorKeyHex = await coreKit.enableMFA({});
 85→
 86→      // Commit the MFA changes
 87→      await coreKit.commitChanges();
 88→
 89→      // Defensive check: verify TSS public key unchanged after MFA enrollment (MFA-04)
 90→      const postMfaTssPub = coreKit.getKeyDetails().tssPubKey;
 91→      if (preMfaTssPub?.x && preMfaTssPub?.y && postMfaTssPub?.x && postMfaTssPub?.y) {
 92→        const preX = preMfaTssPub.x.toString('hex');
 93→        const preY = preMfaTssPub.y.toString('hex');
 94→        const postX = postMfaTssPub.x.toString('hex');
 95→        const postY = postMfaTssPub.y.toString('hex');
 96→        if (preX !== postX || preY !== postY) {
 97→          throw new Error(
 98→            'MFA enrollment failed: TSS public key changed. Your keypair identity is no longer stable. Please contact support.'
 99→          );
100→        }
101→      }
102→
103→      // Convert to 24-word mnemonic for user display
104→      const mnemonic = keyToMnemonic(backupFactorKeyHex);
105→
106→      // Update store with new key details
107→      const details = coreKit.getKeyDetails();
108→      useMfaStore.getState().setMfaEnabled(true);
109→      useMfaStore.getState().setFactorDetails(details.totalFactors, details.threshold);
110→
111→      return mnemonic;
112→    } finally {
113→      useMfaStore.getState().setEnrolling(false);
114→    }
115→  }, [coreKit]);
116→
117→  /**
118→   * Input a factor key (hex string) to complete REQUIRED_SHARE login.
119→   * Used for both recovery and cross-device approval flows.
120→   */
121→  const inputFactorKey = useCallback(
122→    async (factorKeyHex: string): Promise<void> => {
123→      if (!coreKit) throw new Error('Core Kit not initialized');
124→      const factorKey = new BN(factorKeyHex, 'hex');
125→      await coreKit.inputFactorKey(factorKey);
126→      syncStatus();
127→    },
128→    [coreKit, syncStatus]
129→  );
130→
131→  /**
132→   * Recover with a 24-word mnemonic phrase.
133→   * After recovery, creates a device factor for the new device.
134→   */
135→  const recoverWithMnemonic = useCallback(
136→    async (mnemonic: string): Promise<void> => {
137→      if (!coreKit) throw new Error('Core Kit not initialized');
138→
139→      // Convert mnemonic to factor key hex
140→      const factorKeyHex = mnemonicToKey(mnemonic.trim().toLowerCase());
141→      await inputFactorKey(factorKeyHex);
142→
143→      // Create a device factor for this new device
144→      const newDeviceFactor = generateFactorKey();
145→      await coreKit.createFactor({
146→        shareType: TssShareType.DEVICE,
147→        factorKey: newDeviceFactor.private,
148→        shareDescription: FactorKeyTypeShareDescription.DeviceShare,
149→      });
150→      await coreKit.setDeviceFactor(newDeviceFactor.private);
151→      await coreKit.commitChanges();
152→    },
153→    [coreKit, inputFactorKey]
154→  );
155→
156→  /**
157→   * Get all factors with their descriptions.
158→   * shareDescriptions is Record<string, string[]> where keys are factor pub hex.
159→   */
160→  const getFactors = useCallback((): FactorInfo[] => {
161→    if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) return [];
162→    try {
163→      const details = coreKit.getKeyDetails();
164→      const factors: FactorInfo[] = [];
165→
166→      for (const [factorPubHex, descriptions] of Object.entries(details.shareDescriptions)) {
167→        for (const descJson of descriptions) {
168→          try {
169→            const parsed = JSON.parse(descJson) as {
170→              module?: string;
171→              additionalMetadata?: Record<string, string>;
172→            };
173→            factors.push({
174→              factorPubHex,
175→              description: parsed.module || 'unknown',
176→              type: parsed.module || 'unknown',
177→              additionalMetadata: parsed.additionalMetadata,
178→            });
179→          } catch {
180→            factors.push({
181→              factorPubHex,
182→              description: 'unknown',
183→              type: 'unknown',
184→            });
185→          }
186→        }
187→      }
188→
189→      return factors;
190→    } catch {
191→      return [];
192→    }
193→  }, [coreKit]);
194→
195→  /**
196→   * Delete a factor by its public key hex.
197→   * Cannot delete the currently active factor or the last remaining factor.
198→   */
199→  const deleteFactor = useCallback(
200→    async (factorPubHex: string): Promise<void> => {
201→      if (!coreKit) throw new Error('Core Kit not initialized');
202→      const factorPub = Point.fromSEC1(factorKeyCurve, factorPubHex);
203→      await coreKit.deleteFactor(factorPub);
204→      await coreKit.commitChanges();
205→    },
206→    [coreKit]
207→  );
208→
209→  /**
210→   * Get the current active factor key and share type.
211→   */
212→  const getCurrentFactorKey = useCallback((): {
213→    factorKey: BN;
214→    shareType: TssShareType;
215→  } | null => {
216→    if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) return null;
217→    try {
218→      return coreKit.getCurrentFactorKey();
219→    } catch {
220→      return null;
221→    }
222→  }, [coreKit]);
223→
224→  /**
225→   * Regenerate the recovery phrase.
226→   * Deletes the old recovery factor and creates a new one.
227→   * Returns the new 24-word mnemonic.
228→   */
229→  const regenerateRecoveryPhrase = useCallback(async (): Promise<string> => {
230→    if (!coreKit) throw new Error('Core Kit not initialized');
231→    if (coreKit.status !== COREKIT_STATUS.LOGGED_IN) {
232→      throw new Error('Must be logged in to regenerate recovery phrase');
233→    }
234→
235→    // Find the existing recovery (seedPhrase) factor
236→    const factors = getFactors();
237→    const recoveryFactor = factors.find((f) => f.type === FactorKeyTypeShareDescription.SeedPhrase);
238→
239→    if (recoveryFactor) {
240→      // Delete old recovery factor
241→      const factorPub = Point.fromSEC1(factorKeyCurve, recoveryFactor.factorPubHex);
242→      await coreKit.deleteFactor(factorPub);
243→    }
244→
245→    // Generate new recovery factor
246→    const newRecovery = generateFactorKey();
247→    await coreKit.createFactor({
248→      shareType: TssShareType.RECOVERY,
249→      factorKey: newRecovery.private,
250→      shareDescription: FactorKeyTypeShareDescription.SeedPhrase,
251→    });
252→    await coreKit.commitChanges();
253→
254→    // Convert the new factor key to mnemonic
255→    // Zero-pad to 64 hex chars (32 bytes)
256→    const factorKeyHex = newRecovery.private.toString('hex').padStart(64, '0');
257→    return keyToMnemonic(factorKeyHex);
258→  }, [coreKit, getFactors]);
259→
260→  return {
261→    // State from store
262→    isMfaEnabled,
263→    isEnrolling,
264→    factorCount,
265→    threshold,
266→
267→    // Operations
268→    checkMfaStatus,
269→    enableMfa,
270→    inputFactorKey,
271→    recoverWithMnemonic,
272→    getFactors,
273→    deleteFactor,
274→    getCurrentFactorKey,
275→    regenerateRecoveryPhrase,
276→  };
277→}
