 23→import { clearFileSizeCache } from './useFileSize';
 24→
 25→export function useAuth() {
 26→  const navigate = useNavigate();
 27→  const {
 28→    isLoggedIn: coreKitLoggedIn,
 29→    isInitialized: coreKitInitialized,
 30→    isRequiredShare,
 31→    loginWithGoogle: coreKitLoginGoogle,
 32→    loginWithEmailOtp: coreKitLoginEmail,
 33→    loginWithWallet: coreKitLoginWallet,
 34→    getVaultKeypair,
 35→    getPublicKeyHex,
 36→    logout: coreKitLogout,
 37→  } = useCoreKitAuth();
 38→  const {
 39→    accessToken,
 40→    isAuthenticated,
 41→    lastAuthMethod,
 42→    userEmail,
 43→    setAccessToken,
 44→    setLastAuthMethod,
 45→    setUserEmail,
 46→    setVaultKeypair,
 47→    logout: clearAuthState,
 48→  } = useAuthStore();
 49→
 50→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 51→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 52→  const restoringRef = useRef(false);
 53→
 54→  // Stable refs for functions used in the session restoration effect.
 55→  // This prevents the effect from re-firing when function references change.
 56→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 57→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 58→
 59→  // Pending auth state for REQUIRED_SHARE flow
 60→  // Stored so completeRequiredShare() can resume after factor input
 61→  const [pendingCipherboxJwt, setPendingCipherboxJwt] = useState<string | null>(null);
 62→  const [pendingAuthMethod, setPendingAuthMethod] = useState<string | null>(null);
 63→
 64→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 65→
 66→  // Get vault store actions
 67→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 68→
 69→  /**
 70→   * Initialize vault for new users or load existing vault keys.
 71→   * Called after successful backend authentication.
 72→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 73→   */
 74→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 75→    // Get user's secp256k1 keypair from Core Kit TSS export
 76→    const userKeypair = await getVaultKeypair();
 77→
 78→    if (!userKeypair) {
 79→      throw new Error('Failed to get vault keypair from Core Kit');
 80→    }
 81→
 82→    // Store keypair in auth store for crypto operations
 83→    setVaultKeypair(userKeypair);
 84→
 85→    try {
 86→      // Try to fetch existing vault
 87→      const existingVault = await vaultApi.getVault();
 88→
 89→      // Store TEE keys if available
 90→      if (existingVault.teeKeys) {
 91→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
 92→      }
 93→
 94→      // Vault exists - decrypt keys and load into store
 95→      // decryptVaultKeys derives the IPNS public key internally from the decrypted private key
 96→      const decryptedVault = await decryptVaultKeys(
 97→        {
 98→          encryptedRootFolderKey: hexToBytes(existingVault.encryptedRootFolderKey),
 99→          encryptedIpnsPrivateKey: hexToBytes(existingVault.encryptedRootIpnsPrivateKey),
100→        },
101→        userKeypair.privateKey
102→      );
103→
104→      setVaultKeys({
105→        rootFolderKey: decryptedVault.rootFolderKey,
106→        rootIpnsKeypair: decryptedVault.rootIpnsKeypair,
107→        rootIpnsName: existingVault.rootIpnsName,
108→        vaultId: existingVault.id,
109→      });
110→    } catch (error) {
111→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
112→
113→      if (is404) {
114→        // New user - initialize vault
115→        console.log(
116→          '[Auth] New user on Core Kit. If migrating from PnP, vault re-initialization may be needed.'
117→        );
118→        const newVault = await initializeVault(userKeypair.privateKey);
119→        const encryptedVault = await encryptVaultKeys(newVault, userKeypair.publicKey);
120→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
121→
122→        const storedVault = await vaultApi.initVault({
123→          ownerPublicKey: bytesToHex(userKeypair.publicKey),
124→          encryptedRootFolderKey: bytesToHex(encryptedVault.encryptedRootFolderKey),
125→          encryptedRootIpnsPrivateKey: bytesToHex(encryptedVault.encryptedIpnsPrivateKey),
126→          rootIpnsName,
127→        });
128→
129→        if (storedVault.teeKeys) {
130→          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
131→        }
132→
133→        setVaultKeys({
134→          rootFolderKey: newVault.rootFolderKey,
135→          rootIpnsKeypair: newVault.rootIpnsKeypair,
136→          rootIpnsName,
137→          vaultId: storedVault.id,
138→          isNewVault: true,
139→        });
140→      } else {
141→        console.error('[useAuth] Failed to load vault:', error);
142→        throw error;
143→      }
144→    }
145→
146→    // Non-blocking device registry initialization (fire-and-forget)
147→    // Placed after vault load so registry failures never block login
148→    void (async () => {
149→      try {
150→        const deviceKeypair = await getOrCreateDeviceIdentity();
151→        const deviceInfo = detectDeviceInfo();
152→        const result = await initializeOrSyncRegistry({
153→          userPrivateKey: userKeypair.privateKey,
154→          userPublicKey: userKeypair.publicKey,
155→          deviceKeypair,
156→          deviceInfo: { ...deviceInfo, ipHash: '' },
157→        });
158→        if (result) {
159→          useDeviceRegistryStore
160→            .getState()
161→            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
162→        }
163→      } catch (error) {
164→        console.error('[Auth] Device registry init failed (non-blocking):', error);
165→      }
166→    })();
167→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
168→
169→  /**
170→   * Complete backend authentication after Core Kit login.
171→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
172→   * to the backend with loginType 'corekit'. The backend verifies it against
173→   * its own JWKS since CipherBox is the identity provider.
174→   */
175→  const completeBackendAuth = useCallback(
176→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
177→      // 1. Get real publicKey from Core Kit TSS export
178→      const publicKey = await getPublicKeyHex();
179→      if (!publicKey) {
180→        throw new Error('Failed to get publicKey from Core Kit');
181→      }
182→
183→      // publicKey available for debugging via DevTools if needed
184→
185→      // 2. Authenticate with CipherBox backend
186→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
187→      const response = await authApi.login({
188→        idToken: cipherboxJwt,
189→        publicKey,
190→        loginType: 'corekit',
191→      });
192→
193→      // 3. Store access token (refresh token in HTTP-only cookie)
194→      setAccessToken(response.accessToken);
195→
196→      // 4. Remember auth method for UX
197→      setLastAuthMethod(authMethod);
198→
199→      // 5. Initialize or load vault
200→      await initializeOrLoadVault();
201→    },
202→    [getPublicKeyHex, setAccessToken, setLastAuthMethod, initializeOrLoadVault]
203→  );
204→
205→  /**
206→   * Complete the login flow after REQUIRED_SHARE is resolved.
207→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
208→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
209→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
210→   */
211→  const completeRequiredShare = useCallback(async (): Promise<void> => {
212→    const jwt = pendingCipherboxJwt;
213→    const method = pendingAuthMethod;
214→
215→    if (!jwt || !method) {
216→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
217→    }
218→
219→    // Core Kit should now be LOGGED_IN after inputFactorKey()
220→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
221→    await completeBackendAuth(method, jwt);
222→
223→    // Clear pending state
224→    setPendingCipherboxJwt(null);
225→    setPendingAuthMethod(null);
226→
227→    // Navigate to files
228→    navigate('/files');
229→  }, [pendingCipherboxJwt, pendingAuthMethod, completeBackendAuth, navigate]);
230→
231→  /**
232→   * Login with Google OAuth token.
233→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
234→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
235→   */
236→  const loginWithGoogle = useCallback(
237→    async (googleIdToken: string): Promise<void> => {
238→      if (isLoggingIn) return;
239→      setIsLoggingIn(true);
240→      try {
241→        // 1. Core Kit login via CipherBox identity provider
242→        const {
243→          cipherboxJwt,
244→          email,
245→          userId,
246→          status: coreKitStatus,
247→        } = await coreKitLoginGoogle(googleIdToken);
248→
249→        if (coreKitStatus === 'required_share') {
250→          // MFA enabled but device factor missing.
251→          // Store pending auth info for later completion after factor input.
252→          setPendingCipherboxJwt(cipherboxJwt);
253→          setPendingAuthMethod('google');
254→
255→          // Obtain temporary backend access token so the new device can
256→          // call bulletin board API endpoints (device-approval/*).
257→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
258→          // state and we can't export the TSS key yet.
259→          const tempLoginResponse = await authApi.login({
260→            idToken: cipherboxJwt,
261→            publicKey: `pending-core-kit-${userId}`,
262→            loginType: 'corekit',
263→          });
264→          setAccessToken(tempLoginResponse.accessToken);
265→
266→          if (email) {
267→            setUserEmail(email);
268→          }
269→
270→          // Do NOT call completeBackendAuth() or navigate('/files')
271→          // The component tree will see isRequiredShare === true and
272→          // render recovery/approval UI.
273→          return;
274→        }
275→
276→        // Normal path: Core Kit logged in, proceed as before
277→        // 2. Complete backend auth + vault init
278→        await completeBackendAuth('google', cipherboxJwt);
279→
280→        // 3. Store email for UI display (returned from identity endpoint)
281→        if (email) {
282→          setUserEmail(email);
283→        }
284→
285→        // 4. Navigate to files
286→        navigate('/files');
287→      } catch (error) {
288→        console.error('[useAuth] Google login failed:', error);
289→        throw error;
290→      } finally {
291→        setIsLoggingIn(false);
292→      }
293→    },
294→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail, navigate]
295→  );
296→
297→  /**
298→   * Login with Email OTP.
299→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
300→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
301→   */
302→  const loginWithEmail = useCallback(
303→    async (email: string, otp: string): Promise<void> => {
304→      if (isLoggingIn) return;
305→      setIsLoggingIn(true);
306→      try {
307→        // 1. Core Kit login via CipherBox identity provider
308→        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);
309→
310→        if (coreKitStatus === 'required_share') {
311→          setPendingCipherboxJwt(cipherboxJwt);
312→          setPendingAuthMethod('email');
313→
314→          const tempLoginResponse = await authApi.login({
315→            idToken: cipherboxJwt,
316→            publicKey: `pending-core-kit-${userId}`,
317→            loginType: 'corekit',
318→          });
319→          setAccessToken(tempLoginResponse.accessToken);
320→          setUserEmail(email);
321→          return;
322→        }
323→
324→        // Normal path
325→        await completeBackendAuth('email', cipherboxJwt);
326→        setUserEmail(email);
327→        navigate('/files');
328→      } catch (error) {
329→        console.error('[useAuth] Email login failed:', error);
330→        throw error;
331→      } finally {
332→        setIsLoggingIn(false);
333→      }
334→    },
335→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail, navigate]
336→  );
337→
338→  /**
339→   * Login with Wallet (SIWE).
340→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
341→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
342→   */
343→  const loginWithWallet = useCallback(
344→    async (cipherboxJwt: string, userId: string): Promise<void> => {
345→      if (isLoggingIn) return;
346→      setIsLoggingIn(true);
347→      try {
348→        // 1. Core Kit login via CipherBox identity provider
349→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
350→
351→        if (coreKitStatus === 'required_share') {
352→          setPendingCipherboxJwt(cipherboxJwt);
353→          setPendingAuthMethod('wallet');
354→
355→          const tempLoginResponse = await authApi.login({
356→            idToken: cipherboxJwt,
357→            publicKey: `pending-core-kit-${userId}`,
358→            loginType: 'corekit',
359→          });
360→          setAccessToken(tempLoginResponse.accessToken);
361→          return;
362→        }
363→
364→        // Normal path
365→        await completeBackendAuth('wallet', cipherboxJwt);
366→        navigate('/files');
367→      } catch (error) {
368→        console.error('[useAuth] Wallet login failed:', error);
369→        throw error;
370→      } finally {
371→        setIsLoggingIn(false);
372→      }
373→    },
374→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken, navigate]
375→  );
376→
377→  /**
378→   * Legacy login() for backward compatibility with AuthButton.
379→   * With Core Kit, login requires specifying the auth method.
380→   * This will be replaced by the new Login UI in Plan 04.
381→   */
382→  const login = useCallback(async () => {
383→    // Plan 04 will build the new login UI with method selection.
384→    // For now, this is a no-op placeholder that AuthButton calls.
385→    console.warn(
386→      '[useAuth] login() called without method -- ' +
387→        'use loginWithGoogle() or loginWithEmail() instead. ' +
388→        'Plan 04 will provide the new Login UI.'
389→    );
390→  }, []);
391→
392→  // Complete logout: Backend -> Core Kit -> Clear state
393→  const logout = useCallback(async () => {
394→    if (isLoggingOut) return;
395→
396→    setIsLoggingOut(true);
397→    try {
398→      // 1. Call backend logout (clears cookie)
399→      if (accessToken) {
400→        try {
401→          await authApi.logout();
402→        } catch {
403→          // Ignore errors -- we'll clear state anyway
404→        }
405→      }
406→
407→      // 2. Logout Core Kit (clears session from localStorage)
408→      await coreKitLogout();
409→
410→      // 3. Clear local state
411→      // [SECURITY: HIGH-02] Clear vault and folder stores
412→      // BEFORE auth state to zero crypto keys from memory
413→      useFolderStore.getState().clearFolders();
414→      useVaultStore.getState().clearVaultKeys();
415→      useSyncStore.getState().reset();
416→      useDeviceRegistryStore.getState().clearRegistry();
417→      useMfaStore.getState().reset();
418→      clearFileSizeCache();
419→      clearAuthState();
420→
421→      // 4. Clear pending REQUIRED_SHARE state
422→      setPendingCipherboxJwt(null);
423→      setPendingAuthMethod(null);
424→
425→      // 5. Navigate to login
426→      navigate('/');
427→    } catch (error) {
428→      console.error('[useAuth] Logout failed:', error);
429→      // Still clear state even if backend fails
430→      useFolderStore.getState().clearFolders();
431→      useVaultStore.getState().clearVaultKeys();
432→      useSyncStore.getState().reset();
433→      useDeviceRegistryStore.getState().clearRegistry();
434→      useMfaStore.getState().reset();
435→      clearFileSizeCache();
436→      clearAuthState();
437→      setPendingCipherboxJwt(null);
438→      setPendingAuthMethod(null);
439→      navigate('/');
440→    } finally {
441→      setIsLoggingOut(false);
442→    }
443→  }, [accessToken, coreKitLogout, clearAuthState, navigate, isLoggingOut]);
444→
445→  // Keep function refs up-to-date for use in session restoration effect.
446→  // Using refs prevents the effect from re-firing when function identities change.
447→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
448→  coreKitLogoutRef.current = coreKitLogout;
449→
450→  // Session restoration: if Core Kit restores a session from localStorage
451→  // on init, we have LOGGED_IN status without going through login flow.
452→  // Complete backend auth + vault loading.
453→  useEffect(() => {
454→    const restoreSession = async () => {
455→      // Only restore if Core Kit has a session but we don't have
456→      // a backend access token yet
457→      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
458→        restoringRef.current = true;
459→        setIsLoggingIn(true);
460→        try {
461→          // Try to refresh using the HTTP-only cookie first
462→          const response = await authApi.refresh();
463→          setAccessToken(response.accessToken);
464→
465→          // Restore email from backend if available
466→          if (response.email) {
467→            setUserEmail(response.email);
468→          }
469→
470→          // Load vault keys from Core Kit keypair
471→          await initializeOrLoadVaultRef.current?.();
472→        } catch {
473→          // No valid backend session -- user needs to re-login
474→          // Core Kit session exists but backend cookie expired
475→          // Clear Core Kit session to avoid inconsistent state
476→          try {
477→            await coreKitLogoutRef.current?.();
478→          } catch {
479→            // Ignore logout errors during cleanup
480→          }
481→        } finally {
482→          restoringRef.current = false;
483→          setIsLoggingIn(false);
484→        }
485→      }
486→    };
487→    restoreSession();
488→  }, [coreKitLoggedIn, isAuthenticated, isLoggingIn, setAccessToken, setUserEmail]);
489→
490→  return {
491→    isLoading,
492→    isAuthenticated,
493→    isRequiredShare,
494→    lastAuthMethod,
495→    userEmail,
496→    pendingAuthMethod,
497→    login,
498→    loginWithGoogle,
499→    loginWithEmail,
500→    loginWithWallet,
501→    completeRequiredShare,
502→    logout,
503→  };
504→}
