24→export function useMfa() {
25→  const { coreKit, syncStatus } = useCoreKit();
26→
27→  const isMfaEnabled = useMfaStore((s) => s.isMfaEnabled);

  1→import { useCallback } from 'react';
  2→import {
  3→  COREKIT_STATUS,
  4→  generateFactorKey,
  5→  keyToMnemonic,
  6→  mnemonicToKey,
  7→  TssShareType,
  8→  FactorKeyTypeShareDescription,
  9→  factorKeyCurve,
 10→} from '@web3auth/mpc-core-kit';
 11→import { Point } from '@tkey/common-types';
 12→import BN from 'bn.js';
 13→import { useCoreKit } from '../lib/web3auth/core-kit-provider';
 14→import { useMfaStore } from '../stores/mfa.store';
 15→
 16→export type FactorInfo = {
 17→  factorPubHex: string;
 18→  description: string;
 19→  type: string;
 20→  /** Additional metadata set during createFactor (e.g. deviceId, browserName) */
 21→  additionalMetadata?: Record<string, string>;
 22→};
 23→
 24→export function useMfa() {
 25→  const { coreKit } = useCoreKit();
 26→
 27→  const isMfaEnabled = useMfaStore((s) => s.isMfaEnabled);
 28→  const isEnrolling = useMfaStore((s) => s.isEnrolling);
 29→  const factorCount = useMfaStore((s) => s.factorCount);
 30→  const threshold = useMfaStore((s) => s.threshold);
 31→
 32→  /**
 33→   * Check MFA status from Core Kit key details.
 34→   * MFA is enabled when totalFactors > 2 (every account starts with 2
 35→   * default factors: JWT verifier share + hashedShare cloud custodial key).
 36→   */
 37→  const checkMfaStatus = useCallback((): {
 38→    isMfaEnabled: boolean;
 39→    totalFactors: number;
 40→    threshold: number;
 41→  } => {
 42→    if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) {
 43→      return { isMfaEnabled: false, totalFactors: 0, threshold: 0 };
 44→    }
 45→    try {
 46→      const details = coreKit.getKeyDetails();
 47→      const enabled = details.totalFactors > 2;
 48→      useMfaStore.getState().setMfaEnabled(enabled);
 49→      useMfaStore.getState().setFactorDetails(details.totalFactors, details.threshold);
 50→      return {
 51→        isMfaEnabled: enabled,
 52→        totalFactors: details.totalFactors,
 53→        threshold: details.threshold,
 54→      };
 55→    } catch {
 56→      return { isMfaEnabled: false, totalFactors: 0, threshold: 0 };
 57→    }
 58→  }, [coreKit]);
 59→
 60→  /**
 61→   * Enable MFA. Returns 24-word recovery mnemonic.
 62→   * CRITICAL: commitChanges() must be called before enableMFA() in manualSync mode.
 63→   */
 64→  const enableMfa = useCallback(async (): Promise<string> => {
 65→    if (!coreKit) throw new Error('Core Kit not initialized');
 66→    if (coreKit.status !== COREKIT_STATUS.LOGGED_IN) {
 67→      throw new Error('Must be logged in to enable MFA');
 68→    }
 69→
 70→    const store = useMfaStore.getState();
 71→    if (store.isMfaEnabled) {
 72→      throw new Error('MFA is already enabled');
 73→    }
 74→
 75→    useMfaStore.getState().setEnrolling(true);
 76→    try {
 77→      // Commit any pending changes first (CRITICAL for manualSync mode -- Pitfall 1)
 78→      await coreKit.commitChanges();
 79→
 80→      // Capture TSS public key BEFORE enableMFA for stability verification (MFA-04)
 81→      const preMfaTssPub = coreKit.getKeyDetails().tssPubKey;
 82→
 83→      // enableMFA creates device factor + recovery factor atomically
 84→      const backupFactorKeyHex = await coreKit.enableMFA({});
 85→
 86→      // Commit the MFA changes
 87→      await coreKit.commitChanges();
 88→
 89→      // Defensive check: verify TSS public key unchanged after MFA enrollment (MFA-04)
 90→      const postMfaTssPub = coreKit.getKeyDetails().tssPubKey;
 91→      if (preMfaTssPub?.x && preMfaTssPub?.y && postMfaTssPub?.x && postMfaTssPub?.y) {
 92→        const preX = preMfaTssPub.x.toString('hex');
 93→        const preY = preMfaTssPub.y.toString('hex');
 94→        const postX = postMfaTssPub.x.toString('hex');
 95→        const postY = postMfaTssPub.y.toString('hex');
 96→        if (preX !== postX || preY !== postY) {
 97→          throw new Error(
 98→            'MFA enrollment failed: TSS public key changed. Your keypair identity is no longer stable. Please contact support.'
 99→          );
100→        }
101→      }
102→
103→      // Convert to 24-word mnemonic for user display
104→      const mnemonic = keyToMnemonic(backupFactorKeyHex);
105→
106→      // Update store with new key details
107→      const details = coreKit.getKeyDetails();
108→      useMfaStore.getState().setMfaEnabled(true);
109→      useMfaStore.getState().setFactorDetails(details.totalFactors, details.threshold);
110→
111→      return mnemonic;
112→    } finally {
113→      useMfaStore.getState().setEnrolling(false);
114→    }
115→  }, [coreKit]);
116→
117→  /**
118→   * Input a factor key (hex string) to complete REQUIRED_SHARE login.
119→   * Used for both recovery and cross-device approval flows.
120→   *
121→   * IMPORTANT: Does NOT call syncStatus() because doing so would transition
122→   * Core Kit's React context to LOGGED_IN, which triggers the session
123→   * restoration effect in useAuth.ts. Since backend auth hasn't completed yet
124→   * (no valid access token or refresh cookie), the session restore fails and
125→   * calls coreKitLogout(), effectively undoing the recovery.
126→   *
127→   * The caller (completeRequiredShare) is responsible for syncing status
128→   * AFTER backend auth completes.
129→   */
130→  const inputFactorKey = useCallback(
131→    async (factorKeyHex: string): Promise<void> => {
132→      if (!coreKit) throw new Error('Core Kit not initialized');
133→      const factorKey = new BN(factorKeyHex, 'hex');
134→      await coreKit.inputFactorKey(factorKey);
135→      // syncStatus() deliberately omitted — see comment above
136→    },
137→    [coreKit]
138→  );
139→
140→  /**
141→   * Recover with a 24-word mnemonic phrase.
142→   * After recovery, creates a device factor for the new device.
143→   */
144→  const recoverWithMnemonic = useCallback(
145→    async (mnemonic: string): Promise<void> => {
146→      if (!coreKit) throw new Error('Core Kit not initialized');
147→
148→      // Convert mnemonic to factor key hex
149→      const factorKeyHex = mnemonicToKey(mnemonic.trim().toLowerCase());
150→      await inputFactorKey(factorKeyHex);
151→
152→      // Create a device factor for this new device
153→      const newDeviceFactor = generateFactorKey();
154→      await coreKit.createFactor({
155→        shareType: TssShareType.DEVICE,
156→        factorKey: newDeviceFactor.private,
157→        shareDescription: FactorKeyTypeShareDescription.DeviceShare,
158→      });
159→      await coreKit.setDeviceFactor(newDeviceFactor.private);
160→      await coreKit.commitChanges();
161→    },
162→    [coreKit, inputFactorKey]
163→  );
164→
165→  /**
166→   * Get all factors with their descriptions.
167→   * shareDescriptions is Record<string, string[]> where keys are factor pub hex.
168→   */
169→  const getFactors = useCallback((): FactorInfo[] => {
170→    if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) return [];
171→    try {
172→      const details = coreKit.getKeyDetails();
173→      const factors: FactorInfo[] = [];
174→
175→      for (const [factorPubHex, descriptions] of Object.entries(details.shareDescriptions)) {
176→        for (const descJson of descriptions) {
177→          try {
178→            const parsed = JSON.parse(descJson) as {
179→              module?: string;
180→              additionalMetadata?: Record<string, string>;
181→            };
182→            factors.push({
183→              factorPubHex,
184→              description: parsed.module || 'unknown',
185→              type: parsed.module || 'unknown',
186→              additionalMetadata: parsed.additionalMetadata,
187→            });
188→          } catch {
189→            factors.push({
190→              factorPubHex,
191→              description: 'unknown',
192→              type: 'unknown',
193→            });
194→          }
195→        }
196→      }
197→
198→      return factors;
199→    } catch {
200→      return [];
201→    }
202→  }, [coreKit]);
203→
204→  /**
205→   * Delete a factor by its public key hex.
206→   * Cannot delete the currently active factor or the last remaining factor.
207→   */
208→  const deleteFactor = useCallback(
209→    async (factorPubHex: string): Promise<void> => {
210→      if (!coreKit) throw new Error('Core Kit not initialized');
211→      const factorPub = Point.fromSEC1(factorKeyCurve, factorPubHex);
212→      await coreKit.deleteFactor(factorPub);
213→      await coreKit.commitChanges();
214→    },
215→    [coreKit]
216→  );
217→
218→  /**
219→   * Get the current active factor key and share type.
220→   */
221→  const getCurrentFactorKey = useCallback((): {
222→    factorKey: BN;
223→    shareType: TssShareType;
224→  } | null => {
225→    if (!coreKit || coreKit.status !== COREKIT_STATUS.LOGGED_IN) return null;
226→    try {
227→      return coreKit.getCurrentFactorKey();
228→    } catch {
229→      return null;
230→    }
231→  }, [coreKit]);
232→
233→  /**
234→   * Regenerate the recovery phrase.
235→   * Deletes the old recovery factor and creates a new one.
236→   * Returns the new 24-word mnemonic.
237→   */
238→  const regenerateRecoveryPhrase = useCallback(async (): Promise<string> => {
239→    if (!coreKit) throw new Error('Core Kit not initialized');
240→    if (coreKit.status !== COREKIT_STATUS.LOGGED_IN) {
241→      throw new Error('Must be logged in to regenerate recovery phrase');
242→    }
243→
244→    // Find the existing recovery (seedPhrase) factor
245→    const factors = getFactors();
246→    const recoveryFactor = factors.find((f) => f.type === FactorKeyTypeShareDescription.SeedPhrase);
247→
248→    if (recoveryFactor) {
249→      // Delete old recovery factor
250→      const factorPub = Point.fromSEC1(factorKeyCurve, recoveryFactor.factorPubHex);
251→      await coreKit.deleteFactor(factorPub);
252→    }
253→
254→    // Generate new recovery factor
255→    const newRecovery = generateFactorKey();
256→    await coreKit.createFactor({
257→      shareType: TssShareType.RECOVERY,
258→      factorKey: newRecovery.private,
259→      shareDescription: FactorKeyTypeShareDescription.SeedPhrase,
260→    });
261→    await coreKit.commitChanges();
262→
263→    // Convert the new factor key to mnemonic
264→    // Zero-pad to 64 hex chars (32 bytes)
265→    const factorKeyHex = newRecovery.private.toString('hex').padStart(64, '0');
266→    return keyToMnemonic(factorKeyHex);
267→  }, [coreKit, getFactors]);
268→
269→  return {
270→    // State from store
271→    isMfaEnabled,
272→    isEnrolling,
273→    factorCount,
274→    threshold,
275→
276→    // Operations
277→    checkMfaStatus,
278→    enableMfa,
279→    inputFactorKey,
280→    recoverWithMnemonic,
281→    getFactors,
282→    deleteFactor,
283→    getCurrentFactorKey,
284→    regenerateRecoveryPhrase,
285→  };
286→}
