  1→import { useCallback, useEffect, useRef, useState } from 'react';
  2→import { useDeviceApproval, type ApprovalStatus } from '../../hooks/useDeviceApproval';
  3→import { useAuthStore } from '../../stores/auth.store';
  4→
  5→type DeviceWaitingScreenProps = {
  6→  onRecoveryFallback: () => void;
  7→  onApprovalComplete: () => void;
  8→};
  9→
 10→const APPROVAL_TTL_MS = 5 * 60 * 1000; // 5 minutes
 11→const COUNTDOWN_WARNING_MS = 3 * 60 * 1000; // 3 minutes remaining
 12→
 13→/**
 14→ * Full-screen waiting component shown when a new device is in
 15→ * REQUIRED_SHARE state. Creates a bulletin board approval request
 16→ * and polls for a response from an existing device.
 17→ *
 18→ * Displays a spinner, countdown timer, and a fallback link to
 19→ * use a recovery phrase instead.
 20→ */
 21→export function DeviceWaitingScreen({
 22→  onRecoveryFallback,
 23→  onApprovalComplete,
 24→}: DeviceWaitingScreenProps) {
 25→  const { requestApproval, cancelRequest, approvalStatus, approvalError } = useDeviceApproval();
 26→  const accessToken = useAuthStore((s) => s.accessToken);
 27→
 28→  const [countdown, setCountdown] = useState(APPROVAL_TTL_MS);
 29→  const startTimeRef = useRef<number>(Date.now());
 30→  const countdownRef = useRef<ReturnType<typeof setInterval> | null>(null);
 31→  const requestFiredRef = useRef(false);
 32→
 33→  // Start the approval request once the temp access token is available.
 34→  // The token is obtained asynchronously in loginWithGoogle/Email/Wallet
 35→  // AFTER syncStatus() sets isRequiredShare=true, so this component may
 36→  // mount before the token is stored. We wait for it to avoid a 401.
 37→  useEffect(() => {
 38→    if (!accessToken || requestFiredRef.current) return;
 39→    requestFiredRef.current = true;
 40→
 41→    startTimeRef.current = Date.now();
 42→    requestApproval();
 43→
 44→    // Countdown timer
 45→    countdownRef.current = setInterval(() => {
 46→      const elapsed = Date.now() - startTimeRef.current;
 47→      const remaining = Math.max(0, APPROVAL_TTL_MS - elapsed);
 48→      setCountdown(remaining);
 49→    }, 1000);
 50→  }, [accessToken, requestApproval]);
 51→
 52→  // Cleanup on unmount: clear countdown timer and cancel pending request
 53→  useEffect(() => {
 54→    return () => {
 55→      if (countdownRef.current) {
 56→        clearInterval(countdownRef.current);
 57→      }
 58→      cancelRequest();
 59→    };
 60→  }, [cancelRequest]);
 61→
 62→  // Auto-complete when approval succeeds
 63→  useEffect(() => {
 64→    if (approvalStatus === 'approved') {
 65→      onApprovalComplete();
 66→    }
 67→  }, [approvalStatus, onApprovalComplete]);
 68→
 69→  const handleRetry = useCallback(() => {
 70→    startTimeRef.current = Date.now();
 71→    setCountdown(APPROVAL_TTL_MS);
 72→    requestApproval();
 73→  }, [requestApproval]);
 74→
 75→  const minutes = Math.floor(countdown / 60000);
 76→  const seconds = Math.floor((countdown % 60000) / 1000);
 77→  const timeDisplay = `${minutes}:${seconds.toString().padStart(2, '0')}`;
 78→  const isWarning = countdown <= COUNTDOWN_WARNING_MS && countdown > 0;
 79→
 80→  return (
 81→    <div className="device-waiting">
 82→      <div className="device-waiting-card">
 83→        <h2 className="device-waiting-title">{'// waiting for device approval'}</h2>
 84→
 85→        {renderContent(approvalStatus, {
 86→          timeDisplay,
 87→          isWarning,
 88→          countdown,
 89→          approvalError,
 90→          onRecoveryFallback,
 91→          handleRetry,
 92→        })}
 93→      </div>
 94→    </div>
 95→  );
 96→}
 97→
 98→function renderContent(
 99→  status: ApprovalStatus,
100→  props: {
101→    timeDisplay: string;
102→    isWarning: boolean;
103→    countdown: number;
104→    approvalError: string | null;
105→    onRecoveryFallback: () => void;
106→    handleRetry: () => void;
107→  }
108→) {
109→  const { timeDisplay, isWarning, countdown, approvalError, onRecoveryFallback, handleRetry } =
110→    props;
111→
112→  if (status === 'denied') {
113→    return (
114→      <div className="device-waiting-content">
115→        <div className="device-waiting-status-message device-waiting-denied">
116→          Request was denied by another device.
117→        </div>
118→        <div className="device-waiting-actions">
119→          <button type="button" className="device-waiting-btn" onClick={handleRetry}>
120→            --retry
121→          </button>
122→          <button type="button" className="device-waiting-link" onClick={onRecoveryFallback}>
123→            use recovery phrase instead
124→          </button>
125→        </div>
126→      </div>
127→    );
128→  }
129→
130→  if (status === 'expired') {
131→    return (
132→      <div className="device-waiting-content">
133→        <div className="device-waiting-status-message device-waiting-expired">
134→          Request expired. No device responded within the time limit.
135→        </div>
136→        <div className="device-waiting-actions">
137→          <button type="button" className="device-waiting-btn" onClick={handleRetry}>
138→            --retry
139→          </button>
140→          <button type="button" className="device-waiting-link" onClick={onRecoveryFallback}>
141→            use recovery phrase instead
142→          </button>
143→        </div>
144→      </div>
145→    );
146→  }
147→
148→  if (status === 'error') {
149→    return (
150→      <div className="device-waiting-content">
151→        <div className="device-waiting-status-message device-waiting-error">
152→          {approvalError || 'An error occurred.'}
153→        </div>
154→        <div className="device-waiting-actions">
155→          <button type="button" className="device-waiting-btn" onClick={handleRetry}>
156→            --retry
157→          </button>
158→          <button type="button" className="device-waiting-link" onClick={onRecoveryFallback}>
159→            use recovery phrase instead
160→          </button>
161→        </div>
162→      </div>
163→    );
164→  }
165→
166→  if (status === 'completing') {
167→    return (
168→      <div className="device-waiting-content">
169→        <span className="device-waiting-spinner" aria-hidden="true" />
170→        <p className="device-waiting-text">Approval received. Completing login...</p>
171→      </div>
172→    );
173→  }
174→
175→  // Default: requesting/pending
176→  return (
177→    <div className="device-waiting-content">
178→      <span className="device-waiting-spinner" aria-hidden="true" />
179→      <p className="device-waiting-text">
180→        Request sent to your other devices. Open CipherBox on an authorized device to approve this
181→        login.
182→      </p>
183→      <div
184→        className={`device-waiting-countdown ${isWarning ? 'warning' : ''}`}
185→        aria-label={`Time remaining: ${timeDisplay}`}
186→      >
187→        {countdown > 0 ? timeDisplay : 'expired'}
188→      </div>
189→      <button type="button" className="device-waiting-link" onClick={onRecoveryFallback}>
190→        use recovery phrase instead
191→      </button>
192→    </div>
193→  );
194→}
